class Rejected(Exception):
    pass

class ImageRec:
    __slots__ = ("accept", "rows", "cell_count", "refs")
    def __init__(self, image, cell_count):
        self.accept = image["accept"]
        self.rows = image["rows"]
        self.cell_count = cell_count
        self.refs = 0

class Context:
    __slots__ = ("epoch", "state")
    def __init__(self, epoch, state):
        self.epoch = epoch
        self.state = state

# Context collections are persistent immutable treaps.  A clone can share
# its parent's whole snapshot in O(1), while later single-context changes use
# path copying in O(log n).  Contexts themselves are immutable, so sharing
# them is observationally identical to a by-value copy and avoids the
# quadratic clone/exit behaviour of eagerly materialising every copy.
_M64 = (1 << 64) - 1

def _priority(key):
    x = (key + 0x9E3779B97F4A7C15) & _M64
    x = ((x ^ (x >> 30)) * 0xBF58476D1CE4E5B9) & _M64
    x = ((x ^ (x >> 27)) * 0x94D049BB133111EB) & _M64
    return x ^ (x >> 31)

def _rot_right(t):
    # t = (key, value, priority, left, right)
    l = t[3]
    return (l[0], l[1], l[2], l[3],
            (t[0], t[1], t[2], l[4], t[4]))

def _rot_left(t):
    r = t[4]
    return (r[0], r[1], r[2],
            (t[0], t[1], t[2], t[3], r[3]), r[4])

def _treap_insert(t, key, value):
    if t is None:
        return (key, value, _priority(key), None, None)
    tk = t[0]
    if key == tk:
        return (tk, value, t[2], t[3], t[4])
    if key < tk:
        nl = _treap_insert(t[3], key, value)
        node = (tk, t[1], t[2], nl, t[4])
        if nl[2] < t[2]:
            return _rot_right(node)
        return node
    nr = _treap_insert(t[4], key, value)
    node = (tk, t[1], t[2], t[3], nr)
    if nr[2] < t[2]:
        return _rot_left(node)
    return node

def _treap_merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a[2] < b[2]:
        return (a[0], a[1], a[2], a[3], _treap_merge(a[4], b))
    return (b[0], b[1], b[2], _treap_merge(a, b[3]), b[4])

def _treap_erase(t, key):
    if t is None:
        return None
    tk = t[0]
    if key == tk:
        return _treap_merge(t[3], t[4])
    if key < tk:
        return (tk, t[1], t[2], _treap_erase(t[3], key), t[4])
    return (tk, t[1], t[2], t[3], _treap_erase(t[4], key))

class ContextStore:
    __slots__ = ("root", "hist", "size")
    def __init__(self, root=None, hist=None, size=0):
        self.root = root
        self.hist = {} if hist is None else hist   # immutable by convention
        self.size = size
    def get(self, rid):
        t = self.root
        while t is not None:
            k = t[0]
            if rid == k:
                return t[1]
            t = t[3] if rid < k else t[4]
        return None
    def put(self, rid, ctx):
        hist = dict(self.hist)
        hist[ctx.epoch] = hist.get(ctx.epoch, 0) + 1
        return ContextStore(_treap_insert(self.root, rid, ctx), hist,
                            self.size + 1)
    def remove(self, rid):
        ctx = self.get(rid)
        if ctx is None:
            return None, self
        hist = dict(self.hist)
        n = hist[ctx.epoch] - 1
        if n:
            hist[ctx.epoch] = n
        else:
            del hist[ctx.epoch]
        return ctx, ContextStore(_treap_erase(self.root, rid), hist,
                                 self.size - 1)

class Unit:
    __slots__ = ("ns", "pid", "gen", "service", "mark", "contexts")
    def __init__(self, ns, pid, gen, service, mark=0, contexts=None):
        self.ns = ns
        self.pid = pid
        self.gen = gen
        self.service = service
        self.mark = mark
        self.contexts = ContextStore() if contexts is None else contexts
    @property
    def triple(self):
        return (self.ns, self.pid, self.gen)

class Packet:
    __slots__ = ("epoch", "state", "destination", "wire", "receipt")
    def __init__(self, epoch, state, destination, wire):
        self.epoch = epoch
        self.state = state
        self.destination = destination
        self.wire = wire
        self.receipt = None          # (unit_triple, rid, epoch, state)

class Connection:
    __slots__ = ("gen", "mark", "packets")
    def __init__(self, gen):
        self.gen = gen
        self.mark = 0
        self.packets = {}

class FileRec:
    __slots__ = ("gen", "epoch", "state")
    def __init__(self, gen, epoch, state):
        self.gen = gen
        self.epoch = epoch
        self.state = state

class MemoryMap:
    """Compatibility no-op view of the historical CPU transition map."""
    def __init__(self):
        self.entries = {}
    def __setitem__(self, key, value):
        self.entries[key] = value

class Agent:
    def __init__(self, services, limits):
        self.services = services
        self.limits = limits
        ordered = sorted(services, key=lambda s: s["label"])
        self.sym_of = {s["name"]: i for i, s in enumerate(ordered)}
        self.label_of = {s["name"]: s["label"] for s in services}
        self.m = len(ordered)

        self.images = {}
        self.active = None
        self.stage_hw = 0
        self.cells_used = 0

