    def _spawn(self, e):
        u = e["unit"]
        pair = (u[0], u[1])
        if pair in self.units or u[2] <= self.unit_hw.get(pair, 0):
            raise Rejected()
        service = e["service"]
        if service not in self.sym_of:
            raise Rejected()
        if len(self.units) >= self.limits["units"]:
            raise Rejected()
        unit = Unit(u[0], u[1], u[2], service)
        self.units[pair] = unit
        self.unit_hw[pair] = u[2]
        return {"ok": True}

    def _clone(self, e):
        parent = self._live_unit(e["parent"])
        c = e["child"]
        cpair = (c[0], c[1])
        if cpair in self.units or c[2] <= self.unit_hw.get(cpair, 0):
            raise Rejected()
        shared = parent.contexts
        nctx = shared.size
        if len(self.units) >= self.limits["units"]:
            raise Rejected()
        if self.context_count + nctx > self.limits["contexts"]:
            raise Rejected()
        # Validate every pinned epoch before committing the child.  Live
        # contexts keep their images resident, so this is an invariant check;
        # doing it early also preserves atomicity if state is ever corrupted.
        for ep in shared.hist:
            if ep not in self.images:
                raise Rejected()
        child = Unit(c[0], c[1], c[2], parent.service,
                     mark=parent.mark, contexts=shared)
        # Commit the unit and all logical copies.  The persistent snapshot
        # gives by-value behaviour; each copied context still has its own
        # image reference.
        self.units[cpair] = child
        self.unit_hw[cpair] = c[2]
        self.context_count += nctx
        for ep, count in shared.hist.items():
            self._inc_refs(ep, count)
        return {"ok": True}

    def _exit(self, e):
        u = self._live_unit(e["unit"])
        pair = (u.ns, u.pid)
        for ep, count in u.contexts.hist.items():
            self._dec_refs(ep, count)
        self.context_count -= u.contexts.size
        del self.units[pair]
        return {"ok": True}

    def _begin(self, e):
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        if self.active is None:
            raise Rejected()
        rec = self.images.get(self.active)
        if rec is None or rid <= u.mark or u.contexts.get(rid) is not None:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        state = self._advance(rec, 0, u.service)
        u.contexts = u.contexts.put(rid, Context(self.active, state))
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        return {"ok": True, "epoch": self.active, "state": state}

    def _finish(self, e):
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        ctx, new_store = u.contexts.remove(rid)
        if ctx is None:
            raise Rejected()
        u.contexts = new_store
        self.context_count -= 1
        self._dec_ref(ctx.epoch)
        rec = self.images[ctx.epoch]
        allow = ctx.state != DENY and bool(rec.accept[ctx.state])
        return {"ok": True, "allow": allow}

    def _open(self, e):
        c = e["connection"]
        cid, gen = c[0], c[1]
        if cid in self.connections or gen <= self.conn_hw.get(cid, 0):
            raise Rejected()
        if len(self.connections) >= self.limits["connections"]:
            raise Rejected()
        self.connections[cid] = Connection(gen)
        self.conn_hw[cid] = gen
        return {"ok": True}

    def _send(self, e):
        u = self._live_unit(e["unit"])
        ctx = u.contexts.get(e["rid"])
        if ctx is None:
            raise Rejected()
        conn = self._open_conn(e["connection"])
        stream = e["stream"]
        if stream <= conn.mark:
            raise Rejected()
        destination = e["destination"]
        label = self.label_of.get(destination)
        if label is None:
            raise Rejected()
        if self.packet_count >= self.limits["packets"]:
            raise Rejected()
        wire = self._wire(ctx.epoch, ctx.state, label, stream, conn.gen)
        rec = self.images.get(ctx.epoch)
        if rec is None:
            raise Rejected()
        conn.packets[stream] = Packet(ctx.epoch, ctx.state, destination, wire)
        conn.mark = stream
        self.packet_count += 1
        rec.refs += 1
        return {"ok": True, "wire": wire}

    def _recv(self, e):
        conn = self._open_conn(e["connection"])
        stream = e["stream"]
        packet = conn.packets.get(stream)
        if packet is None:
            raise Rejected()
        u = self._live_unit(e["unit"])
        if u.service != packet.destination:
            raise Rejected()
        wire = e["wire"]
        if wire is not None and not self._wire_ok(wire, packet.wire):
            raise Rejected()
        rid = e["rid"]
        receipt = packet.receipt
        if receipt is not None:
            r_triple, r_rid, r_epoch, r_state = receipt
            if u.triple != r_triple or rid != r_rid:
                raise Rejected()
            ctx = u.contexts.get(rid)
            if ctx is None or ctx.epoch != r_epoch or ctx.state != r_state:
                raise Rejected()
            return {"ok": True, "epoch": r_epoch, "state": r_state}
        if rid <= u.mark or u.contexts.get(rid) is not None:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        rec = self.images.get(packet.epoch)
        if rec is None:
            raise Rejected()
        state = self._advance(rec, packet.state, u.service)
        ctx = Context(packet.epoch, state)
        u.contexts = u.contexts.put(rid, ctx)
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        receipt = (u.triple, rid, packet.epoch, state)
        packet.receipt = receipt
        return {"ok": True, "epoch": packet.epoch, "state": state}

    def _close(self, e):
        conn = self._open_conn(e["connection"])
        cid = e["connection"][0]
        for packet in conn.packets.values():
            self._dec_ref(packet.epoch)
        self.packet_count -= len(conn.packets)
        del self.connections[cid]
        return {"ok": True}

    def _store(self, e):
        u = self._live_unit(e["unit"])
        ctx = u.contexts.get(e["rid"])
        if ctx is None:
            raise Rejected()
        fid, gen = e["file"][0], e["file"][1]
        cur = self.files.get(fid)
        if cur is None:
            if gen <= self.file_hw.get(fid, 0):
                raise Rejected()
            if len(self.files) >= self.limits["files"]:
                raise Rejected()
            self._inc_ref(ctx.epoch)
            self.files[fid] = FileRec(gen, ctx.epoch, ctx.state)
            self.file_hw[fid] = gen
            return {"ok": True}
        if gen != cur.gen:
            raise Rejected()
        old_epoch = cur.epoch
        # Atomic overwrite: adjust the one file reference in place.
        if old_epoch != ctx.epoch:
            self._dec_ref(old_epoch)
            self._inc_ref(ctx.epoch)
        cur.epoch = ctx.epoch
        cur.state = ctx.state
        return {"ok": True}

    def _load(self, e):
        cur = self._current_file(e["file"])
        u = self._live_unit(e["unit"])
        rid = e["rid"]
        if rid <= u.mark or u.contexts.get(rid) is not None:
            raise Rejected()
        if self.context_count >= self.limits["contexts"]:
            raise Rejected()
        rec = self.images.get(cur.epoch)
        if rec is None:
            raise Rejected()
        state = self._advance(rec, cur.state, u.service)
        u.contexts = u.contexts.put(rid, Context(cur.epoch, state))
        u.mark = rid
        self.context_count += 1
        rec.refs += 1
        return {"ok": True, "epoch": cur.epoch, "state": state}

    def _unlink(self, e):
        f = e["file"]
        cur = self._current_file(f)
        self._dec_ref(cur.epoch)
        del self.files[f[0]]
        return {"ok": True}

    def _inspect(self):
        entries = []
        for ep in sorted(self.images):
            rec = self.images[ep]
            entries.append([ep, len(rec.rows), rec.cell_count, rec.refs])
        return {
            "ok": True,
            "active": self.active,
            "images": entries,
            "units": len(self.units),
            "contexts": self.context_count,
            "connections": len(self.connections),
            "packets": self.packet_count,
            "files": len(self.files),
        }
